import { OrdersBoard } from "@/components/admin/OrdersBoard";
import { listOrders } from "@/lib/admin/orders-admin";

export const metadata = { title: "Orders" };

/**
 * Real orders only. This replaced a mock-up full of invented customers and
 * revenue (see orders-admin.ts).
 *
 * PAYMENTS_LIVE stays false until checkout verifies the Razorpay payment
 * signature (HANDOFF §6 A). Until then `completePaymentAction` can mark an
 * order paid without any money moving, and the owner must be told so on the
 * one screen where they would act on it.
 */
const PAYMENTS_LIVE = false;

export default function AdminOrdersRoute() {
  return <OrdersBoard orders={listOrders()} paymentsLive={PAYMENTS_LIVE} />;
}
